export const calculateCarbonFootprint = (data) => {
    const emissionFactors = {
      electricity: 0.5,  // kg CO₂ per kWh
      naturalGas: 5.3,   // kg CO₂ per therm
      vehicleMiles: 0.2, // kg CO₂ per mile
      publicTransport: 0.1, // kg CO₂ per km
      wasteProduced: 0.1,   // kg CO₂ per kg
    };

    const footprint = {
      footprint: (
        (data.electricity || 0) * emissionFactors.electricity +
        (data.naturalGas || 0) * emissionFactors.naturalGas +
        (data.vehicleMiles || 0) * emissionFactors.vehicleMiles +
        (data.publicTransport || 0) * emissionFactors.publicTransport +
        (data.wasteProduced || 0) * emissionFactors.wasteProduced
      ).toFixed(2),

      credits: ((data.electricity || 0) * 0.1).toFixed(2), // 10% credits
      progress: ((data.electricity / 1000) * 100).toFixed(2), // % towards 1000kg goal
      rank: Math.floor(Math.random() * 100), // Random rank (Replace with real logic)
    };

    return footprint;
  };
